import ipaddress

def inventaire(adresses):
    r = {"privées": 0, "publiques": 0, "bouclage": 0, "invalides": []}
    for texte in adresses:
        try:
            ip = ipaddress.ip_address(texte)
        except ValueError:
            r["invalides"].append(texte)
            continue
        if ip.is_loopback:
            r["bouclage"] += 1
        elif ip.is_private:
            r["privées"] += 1
        else:
            r["publiques"] += 1
    return r
